from math import gcd
from functools import reduce
from typing import List

def padic_val_int(p: int, n: int) -> int:
    """Exact power of prime p dividing nonzero integer n."""
    n = abs(n); v = 0
    while n % p == 0:
        n //= p; v += 1
    return v

def content(f: List[int]) -> int:
    """gcd of the coefficients (the content)."""
    return reduce(gcd, (abs(c) for c in f), 0)

def primitive_part(f: List[int]) -> List[int]:
    c = content(f); return [a // c for a in f]

def mu_invariant(p: int, f: List[int]) -> int:
    return padic_val_int(p, content(f))

def lambda_invariant(p: int, f: List[int]) -> int:
    pp = primitive_part(f)
    for i, a in enumerate(pp):
        if a % p != 0:
            return i
    raise RuntimeError("primitive part vanished mod p")

if __name__ == "__main__":
    p = 2
    for f in [[4, 2, 6], [0, 0, 8, 4], [1, 0, 3, 5]]:
        print(f, "-> mu =", mu_invariant(p, f), ", lambda =", lambda_invariant(p, f))

