from functools import reduce
from typing import List

def padic_val_int(p: int, n: int) -> int:
    n = abs(n); v = 0
    while n % p == 0:
        n //= p; v += 1
    return v

def content(f: List[int]) -> int:
    return reduce(gcd, (abs(c) for c in f), 0)

def mu_invariant(p: int, f: List[int]) -> int:
    return padic_val_int(p, content(f))

def lambda_invariant(p: int, f: List[int]) -> int:
    c = content(f)
    for i, a in enumerate(a // c for a in f):
        if a % p != 0:
            return i
    raise RuntimeError

def poly_mul(f: List[int], g: List[int]) -> List[int]:
    out = [0] * (len(f) + len(g) - 1)
    for i, a in enumerate(f):
        for j, b in enumerate(g):
            out[i + j] += a * b
    return out

def check_additivity(p: int, f: List[int], g: List[int]) -> bool:
    fg = poly_mul(f, g)
    mu_ok = mu_invariant(p, fg) == mu_invariant(p, f) + mu_invariant(p, g)
    la_ok = lambda_invariant(p, fg) == lambda_invariant(p, f) + lambda_invariant(p, g)
    return mu_ok and la_ok

if __name__ == "__main__":
    p = 2
    pairs = [([4, 2, 6], [0, 3, 3]), ([0, 0, 8, 4], [1, 0, 2]), ([2, 4, 2], [0, 1])]
    for f, g in pairs:
        print(f, "*", g, "additive:", check_additivity(p, f, g))

