    p = 2; f = [1, 0, 3, 5]
    for (c, k) in [(3, 0), (3, 2), (1, 4), (5, 1)]:
        lhs, rhs, corr = matsuno_twist(p, f, c, k)
        print(f"c={c}, k={k}: lambda(f*tw)={lhs}, formula={rhs}, correction c*mu={corr}, "
              f"nonzero={corr != 0}")

