from math import gcd
from functools import reduce
from typing import List, Tuple

def twist_factor(p: int, c: int, k: int) -> List[int]:
    """The modelled quadratic-twist factor p^k * X^(c*k)."""
    coeffs: List[int] = [0] * (c * k + 1)
    coeffs[c * k] = p ** k
    return coeffs

def poly_mul(f: List[int], g: List[int]) -> List[int]:
    out: List[int] = [0] * (len(f) + len(g) - 1)
    for i, a in enumerate(f):
        for j, b in enumerate(g):
            out[i + j] += a * b
    return out

def _content(f: List[int]) -> int:
    return reduce(gcd, (abs(c) for c in f), 0)

def _mu(p: int, f: List[int]) -> int:
    g = _content(f); v = 0
    while g % p == 0:
        g //= p; v += 1
    return v

def _lambda(p: int, f: List[int]) -> int:
    c = _content(f)
    for i, a in enumerate(f):
        if (a // c) % p != 0:
            return i
    raise RuntimeError

def matsuno_lambda_shift(p: int, f: List[int], c: int, k: int) -> Tuple[int, int, int]:
    """Return (lambda(f*twist), lambda(f) + c*mu(twist), correction term c*mu)."""
    tw = twist_factor(p, c, k)
    mu_tw = _mu(p, tw)
    lhs = _lambda(p, poly_mul(f, tw))
    rhs = _lambda(p, f) + c * mu_tw
    return lhs, rhs, c * mu_tw
